Translate("ruRU", "un-goro-crater", {
	title = "Кратер Ун'Горо",
	aliases = { "Ун'Горо", "Кратер" },
	sections = {
		{
			title = "Обзор",
			text = [=[Кратер Ун'Горо — {link:ogres}огр{/link}омная зеленая чаша, глубоко утопленная в юг {link:kalimdor}Калимдора{/link} и огражденная утесами между песками {link:tanaris}Танариса{/link} и гиблыми пустошами {link:silithus}Силитуса{/link}. Под его кромкой мир словно принадлежит другой эпохе. Над источниками поднимается пар, в сердце кратера дымит вулкан, а джунглями правят звери, которых остальной мир давно забыл: громоподобные дьявозавры, стегодоны, крылатые птеррордаксы и стаи равазавров. В траве блестят странные кристаллы, а на краю диких земель стоят высокие {link:crystal-pylons}кристальные пилоны{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[Ни одна хроника не сообщает, как возник кратер и когда. Предания древнейшей эпохи гласят, что слуги {red:titans}титанов{/red} создали некоторые земли юного мира как сады дикой жизни и что Ун'Горо был в их числе. {link:crystal-pylons}Кристальные пилоны{/link}, стоящие вдоль его кромки, старше любого народа, живущего ныне в {link:kalimdor}Калимдор{/link}е, и никто из нынешних обитателей кратера не может сказать, кто их воздвиг и зачем. {link:tauren}Таурены{/link}, которые приходят сюда охотиться, сильно чувствуют в этой чаше присутствие Матери-Земли. Для них здешние твари — более благородная родня зверей их собственных равнин.]=],
		},
		{
			title = "Наши дни",
			text = [=[В последнее время кратер привлек толпу любопытных и застрявших в пути. Отряд исследователей под началом исследователя {link:williden-marshal}Виллиден{/link}а Маршалла пришел изучать эту землю и едва не был ею уничтожен. Уцелевшие удерживают скалистое убежище на северных высотах, где вокруг них собрались гоблины {link:gadgetzan}Прибамбасска{/link}, странствующие ученые и заблудившиеся путники. {link:cenarion-circle}Круг Кенария{/link} послал за почвой кратера, в которой, как говорят, заключена могучая магия, и друиды в {link:darnassus}Дарнассе{/link} и {link:thunder-bluff}Громовом Утесе{/link} изучают ее. На юге насекомые улья Гориши вгрызлись в землю. Их присутствие тревожит ученых, ибо ничто подобное им не принадлежит естественному порядку кратера. В эти дни карты называют внутри кратера еще и {red:shaper-s-terrace}Террасу Создателя{/red} — место, о котором рассказано на отдельной странице.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}Великие ящеры.{/b} Дьявозавры охотятся по всей чаше. Стегодоны пасутся на юго-западе, равазавры стаями бегают на юго-востоке, а диметрадоны греются вдоль троп.
• {b}Обезьяны Пещеры Лишайников.{/b} Огромные гориллы удерживают пещеры северо-востока и прогоняют всякого, кто подойдет близко.
• {b}Гориши.{/b} Улей насекомых вырыл на юге {link:the-slithering-scar}Скользкий овраг{/link}.
• {b}Элементали.{/b} Существа из живого пламени ходят по склонам вулкана, а из северных ям поднимаются создания из смолы.
• {b}Кровоцветы и слизни.{/b} Плотоядные растения ползут сквозь восточные заросли, а в болотах собираются слизни.
• {b}Пришлые.{/b} Исследователи, механики из {link:gadgetzan}Прибамбасск{/link}а и заблудившиеся странники теснятся в Укрытии Маршалла, а охотник-{link:tauren}таурен{/link} держит собственный лагерь там, где дорога из {link:tanaris}Танарис{/link}а входит в кратер.]=],
		},
		{
			title = "История",
			text = [=[• {b}Эпоха творцов.{/b} Пилоны и кристаллы кратера остались со времен, когда еще не было ни одного королевства смертных. Ни одна летопись смертных не сообщает, как их воздвигли.
• {b}Экспедиция Маршалла.{/b} Отряд, который вел {link:williden-marshal}Виллиден Маршалл{/link}, разбил лагеря на юго-западе и северо-востоке кратера. Звери смели оба, и уцелевшие бежали на север, на возвышенность.
• {b}Наши дни.{/b} Теперь в кратер стремятся ученые, друиды, охотники и по меньшей мере один странник, который не может вспомнить, зачем пришел.]=],
		},
		{
			title = "Предания кратера",
			text = [=[• В Укрытии Маршалла говорят, что пилоны и цветные кристаллы в траве связаны между собой и что верное сочетание цветов пробудит их силу.
• {link:krakle}Кракл{/link} из {link:gadgetzan}Прибамбасск{/link}а полагает, что источники {link:golakka-hot-springs}Голакка{/link} берут свой жар у вулкана, хотя его расчеты еще не закончены.
• {link:torwa-pathfinder}Торва Следопыт{/link} предупреждает: {link:lar-korwi}Лар'корви{/link}, {link:ogres}огр{/link}омный равазавр востока, будет целыми днями преследовать всякого, кто украдет у него добычу.]=],
		},
	},
})

Translate("ruRU", "marshal-s-refuge", {
	title = "Укрытие Маршалла",
	sections = {
		{
			title = "Обзор",
			text = [=[Укрытие Маршалла — лагерь из палаток и кухонных костров, разбитый среди скал северной стены кратера. Его основали в бегстве. Когда звери {link:un-goro-crater}Ун'Горо{/link} смели лагеря Экспедиции Маршалла, {link:williden-marshal}Виллиден Маршалл{/link} и его люди поднялись на эту возвышенность, куда великим ящерам нелегко было за ними последовать. С тех пор к ним присоединились другие: распорядитель полетов из {link:gadgetzan}Прибамбасск{/link}а, заблудившиеся странники, ссорящиеся путники и исследовательница кристаллов, которая работает в пещере над лагерем. Укрытие — единственное место в кратере, где путник может спать, не оставляя один глаз открытым.]=],
		},
	},
})

Translate("ruRU", "fire-plume-ridge", {
	title = "Вулкан Огненного Венца",
	sections = {
		{
			title = "Обзор",
			text = [=[Вулкан Огненного Венца стоит в центре {link:un-goro-crater}Ун'Горо{/link} — обугленный конус, который изливает дым и жар на весь кратер. Его склоны принадлежат элементалям живого пламени. В его сердце, на тропах из почерневшего камня, обитает {link:blazerunner}Огнебег{/link} — элементаль, окутанный аурой, которую не пробил ни один клинок. Он охраняет пещеру, где хранится Золотое Пламя. Жар вулкана так свиреп, что одолевает неосторожных, и исследователь {link:ringo}Ринго{/link} едва от него не погиб. Те, кто изучает кратер, полагают, что вулкан, возможно, греет его источники.]=],
		},
	},
})

Translate("ruRU", "golakka-hot-springs", {
	title = "Горячие источники Голакка",
	aliases = { "Голакка" },
	sections = {
		{
			title = "Обзор",
			text = [=[Горячие источники Голакка парят в западной части кратера — цепь теплых водоемов среди джунглей. {link:krakle}Кракл{/link}, ученый из {link:gadgetzan}Прибамбасск{/link}а, разбил лагерь рядом с ними, вдали от безопасного укрытия. Он хочет знать, откуда берется их жар, и подозревает {link:fire-plume-ridge}Вулкан Огненного Венца{/link}, что неподалеку к востоку. Измерения заставили его задуматься о других источниках, в далеких {link:winterspring}Зимних Ключах{/link}, где никакого вулкана нет.]=],
		},
	},
})

Translate("ruRU", "lakkari-tar-pits", {
	title = "Смоляные ямы Лаккари",
	aliases = { "Лаккари" },
	sections = {
		{
			title = "Обзор",
			text = [=[Смоляные ямы Лаккари лежат на севере кратера, к югу от Укрытия Маршалла. Черная смола пузырится здесь из-под земли широкими липкими лужами. Из нее поднимаются существа из смолы, которые словно живут и движутся по собственной воле. Величайшие из них, владыки смолы, таятся у северных луж. Смоляные твари помельче и ползуны бродят южнее, ближе к равнинам под вулканом. Ни одна запись не сообщает, кто дал ямам их имя.]=],
		},
	},
})

Translate("ruRU", "the-slithering-scar", {
	title = "Скользкий овраг",
	sections = {
		{
			title = "Обзор",
			text = [=[Скользкий овраг — {link:ogres}огр{/link}омный разлом в южном дне кратера, где насекомые Гориши построили свой улей. Воздух над ним полон ос, а по его ходам ползают рабочие, разорители и землерои. В глубоких камерах, увешанных личинками, улей растит свое потомство, и изнутри им правит королева. {link:hol-anyee-marshal}Хол'ани Маршалл{/link} изучала насекомых Гориши, когда ее экспедиция бежала. На ее взгляд, они вовсе не принадлежат кратеру.]=],
		},
	},
})

Translate("ruRU", "terror-run", {
	title = "Путь Ужаса",
	sections = {
		{
			title = "Обзор",
			text = [=[Путь Ужаса — юго-западная равнина кратера, и свое имя она заслужила. Стегодоны пасутся на ней тяжелыми стадами, а среди них охотятся дьявозавры. Экспедиция Маршалла пришла сюда выкапывать кости мертвых зверей. Землекопы скоро обнаружили, что живых гораздо больше и они гораздо опаснее. {link:spark-nilminer}Спарк Нильмайнер{/link}, главный землекоп экспедиции, до сих пор говорит об этом месте с нескрываемым ужасом. Он называет его смертельной ловушкой и говорит это не в шутку.]=],
		},
	},
})

Translate("ruRU", "fungal-rock", {
	title = "Пещера Лишайников",
	sections = {
		{
			title = "Обзор",
			text = [=[Пещера Лишайников — впадина с пещерами на северо-востоке кратера и логово {link:ogres}огр{/link}омных обезьян {link:un-goro-crater}Ун'Горо{/link}. Ее защищают гориллы, топтуны и громовержцы, и нет среди них никого свирепее могучей обезьяны, которую охотник-{link:tauren}таурен{/link} {link:torwa-pathfinder}Торва{/link} зовет {link:u-cha}У'ча{/link}. Изобретательница {link:karna-remtravel}Карна Ремтравел{/link} послала в эти пещеры свою механическую обезьяну {link:a-me-01}А-Ме 01{/link}, чтобы наблюдать за обезьянами вблизи. Обмануть их надолго не удалось. Когда путники вновь нашли машину, она лежала безмолвная и сильно помятая у входа в пещеры.]=],
		},
	},
})

Translate("ruRU", "the-marshlands", {
	title = "Топи",
	sections = {
		{
			title = "Обзор",
			text = [=[Топи — сырые восточные низины кратера, край грязи, тростника и стоячей воды. В его лужах собираются слизни многих видов, а сквозь заросли ползут кровоцветы. Один из брошенных лагерей экспедиции лежал на этой стороне кратера, и его припасы оставались нетронутыми в грязи еще долго после бегства исследователей. Южнее, возле небольшого пруда, лежит разбитый плот — далеко от любой воды, которая могла бы принести его туда. Он принадлежал страннику {link:linken}Линкен{/link}у, хотя тот уже не помнил этого.]=],
		},
	},
})

Translate("ruRU", "crystal-pylons", {
	title = "Кристальные пилоны",
	aliases = { "кристальные пилоны", "пилоны Ун'Горо" },
	sections = {
		{
			title = "Обзор",
			text = [=[Три кристальных пилона стоят в диких землях {link:un-goro-crater}Кратер{/link}а Ун'Горо: один на севере, один у восточной стены и один на западе. Это высокие каменные сооружения, выложенные изнутри кристаллом, и они гораздо старше лагеря любого из ныне живущих исследователей. Долгое время они были лишь слухами, которые пересказывали в Укрытии Маршалла.]=],
		},
		{
			title = "Кристаллы",
			text = [=[Цветные кристаллы разбросаны по дну кратера: красные, синие, желтые и зеленые. Большинство путников не обращает на них внимания. Гномка {link:j-d-collie}Дж. Д. Колли{/link} обратила. Она собирала их мешками и перепробовала все сочетания, какие могла придумать, но кристаллы ничего не выдавали, пока не нашлись пилоны. Когда путники осмотрели все три, она разобрала увиденное ими и записала свои выводы в руководство. С ним кристаллы можно было сплавлять в сочетания, которые восстанавливают, укрепляют, {link:ogres}огр{/link}аждают и заряжают тех, кто их носит.]=],
		},
		{
			title = "Без ответа",
			text = [=[Кто воздвиг пилоны и с какой целью, кратер не говорит. {link:j-d-collie}Дж. Д. Колли{/link} узнала, как пользоваться их кристаллами. Она не узнала, зачем они там.]=],
		},
	},
})

Translate("ruRU", "williden-marshal", {
	title = "Виллиден Маршалл",
	subtitle = "Глава Экспедиции Маршалла",
	found = "Укрытие Маршалла, среди палаток",
	hint = [=[Поговорите с главой экспедиции, которая укрылась на северных высотах кратера.]=],
	allegiance = "Экспедиция Маршалла",
	aliases = { "Виллиден" },
	sections = {
		{
			title = "Обзор",
			text = [=[Виллиден Маршалл возглавляет Экспедицию Маршалла — отряд исследователей, не подчиняющийся ни одному государству. Он привел их в {link:un-goro-crater}Кратер Ун'Горо{/link}, чтобы изучать его, и кратер едва не погубил их всех. Теперь он сберегает то, что осталось от его людей, на скалистых высотах, носящих его имя.]=],
		},
		{
			title = "Значение",
			text = [=[Только благодаря ему в кратере вообще есть безопасное место. {link:the-harborage}Убежище{/link}, которое его люди построили во время бегства, стало местом сбора всех, кто попадает в {link:un-goro-crater}Ун'Горо{/link} — по своей воле или по несчастью. Он не притворяется, будто экспедиция прошла удачно. Он признает, что его отряд слишком легко отнесся к свирепости кратера.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он возглавил экспедицию, которая разбила лагеря на юго-западе и северо-востоке кратера.
• Когда звери смели оба лагеря, он увел уцелевших на север, на возвышенность.
• Он просит путников вернуть припасы и исследовательское снаряжение, которые бросили его люди.
• Он ведет дневник экспедиции, потерянный во время бегства.]=],
		},
		{
			title = "Неизвестное",
			text = [=[Ни одна запись не сообщает, откуда он родом и как основал свой отряд. Здесь записано лишь то, что сделал из него кратер.]=],
		},
	},
	chapters = {
		{
			title = "Спасение экспедиции",
			hint = "Верните то, что экспедиция бросила во время бегства.",
			text = [=[Лагеря покинули в спешке, и вместе с ними пропали и припасы экспедиции, и ее приборы. Без первых исследователи умерли бы с голоду. Без вторых все их страдания оказались бы напрасны. Когда и то и другое принесли в укрытие, Виллиден объявил, что спасена сама экспедиция, и назвал того, кто ее спас, другом своего отряда на всю жизнь.]=],
		},
		{
			title = "Истерзанный дневник",
			hint = "Верните потерянный дневник его владельцу.",
			text = [=[В диких землях нашли изорванный и истоптанный дневник. В нем еще можно было прочесть достаточно, чтобы узнать историю экспедиции: сметенные лагеря, бегство, поиски возвышенности на севере. Виллиден числил его среди многого, что отнял у него кратер. Он был рад получить его обратно.]=],
		},
	},
	mentions = {
		{ text = "Спасение экспедиции" },
		{ text = "Дневник главы экспедиции" },
	},
	bonds = {
		{ id = "hol-anyee-marshal", name = "Хол'ани Маршалл", note = "носит ту же фамилию и служит в той же экспедиции" },
		{ id = "spark-nilminer", name = "Спарк Нильмайнер", note = "его главный землекоп" },
	},
})

Translate("ruRU", "hol-anyee-marshal", {
	title = "Хол'ани Маршалл",
	subtitle = "Ученая Экспедиции Маршалла",
	found = "Укрытие Маршалла, рядом с главой экспедиции",
	hint = [=[Поговорите с ученой экспедиции, которая стоит рядом с ее главой.]=],
