	sections = {
		{
			title = "Обзор",
			text = [=[Хол'ани Маршалл — ученая Экспедиции Маршалла. До того как экспедиция бежала на север, она изучала насекомых Гориши на юге кратера. Отступление не положило конец ее работе. Она считает, что Гориши чужды жизни кратера, и намерена узнать, как они там оказались.]=],
		},
		{
			title = "Значение",
			text = [=[Хол'ани первой сказала вслух, что улью Гориши не место в {link:un-goro-crater}Ун'Горо{/link}.]=],
		},
