Translate("ruRU", "j-d-collie", {
	title = "Дж. Д. Колли",
	subtitle = "Исследовательница кристаллов",
	found = "Пещера над Укрытием Маршалла",
	hint = [=[Найдите гномку, которая работает со светящимися кристаллами в пещере над укрытием.]=],
	allegiance = "Укрытие Маршалла",
	aliases = { "Дж. Д." },
	sections = {
		{
			title = "Обзор",
			text = [=[Дж. Д. Колли — {link:gnomes}гном{/link}ка, устроившая мастерскую в пещере над Укрытием Маршалла. Ее завораживают цветные кристаллы, что лежат в {link:un-goro-crater}Ун'Горо{/link} повсюду, и слухи об {link:ogres}огр{/link}омных пилонах где-то в диких землях. Она готова поверить почти любому рассказу, и в кратере эта доверчивость сослужила ей на удивление добрую службу.]=],
		},
		{
			title = "Значение",
			text = [=[Дж. Д. первой разобралась в кристальных пилонах. Другие годами проходили мимо кристаллов. Она собирала их, испытывала и наконец узнала, как связать их силу. Она также была добра к страннику {link:linken}Линкен{/link}у, когда он впервые набрел на укрытие, и те немногие слова, что он сказал ей в своем смятении, стали ключом к его памяти.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она собирает кристаллы четырех цветов и испытывает их в бесконечных сочетаниях.
• Она посылает путников искать северный, восточный и западный пилоны.
• Она написала руководство о пилонах и кристаллах.
• Она направила поиски забытого прошлого {link:linken}Линкен{/link}а в {link:felwood}Оскверненный лес{/link}, к некоему {link:eridan-bluewind}Эридан{/link}у Синему Ветру.]=],
		},
	},
	chapters = {
		{
			title = "Три пилона",
			hint = "Найдите кристальные пилоны, о которых слышала Дж. Д.",
			text = [=[Долгое время ее опыты ни к чему не приводили, и она начала бояться, что в кристаллах вовсе нет силы. Затем путники нашли пилоны один за другим: один на севере, один у восточной стены, один на западе. Она взяла то, что они видели, и разобрала это в своей пещере. Закончив, она знала, как можно соединять кристаллы, и изложила все это в книге.]=],
		},
		{
			title = "Память гномки",
			hint = [=[Спросите гномку с кристаллами, что когда-то сказал ей потерявшийся странник.]=],
			text = [=[Когда {link:linken}Линкен{/link} впервые пришел в укрытие, он был оглушен и бормотал что-то странное. Дж. Д. запомнила одно из сказанного: он делает тотем, и ему нужно найти в Оскверненном лесу кого-то по имени {link:eridan-bluewind}Эридан Синий Ветер{/link}. Это была тонкая нить, но она привела к самой цели — к {link:blazerunner}Огнебег{/link}у.]=],
		},
	},
	mentions = {
		{ text = "Кристаллы силы" },
		{ text = "Северный пилон" },
		{ text = "Восточный пилон" },
		{ text = "Западный пилон" },
		{ text = "Разобраться во всем" },
		{
			text = [=[Помощь {link:gnomes}гном{/link}ки, по просьбе {link:linken}Линкен{/link}а]=],
		},
		{ text = "Память {link:linken}Линкен{/link}а" },
		{ text = "Аквементас, принесенный ей тотем" },
		{ text = "Приключение {link:linken}Линкен{/link}а" },
	},
	bonds = {
		{ id = "linken", name = "Линкен", note = "она помнила то, что он забыл" },
		{ id = "eridan-bluewind", name = "Эридан Синий Ветер", note = "имя, которое произнес Линкен" },
	},
})

Translate("ruRU", "linken", {
	title = "Линкен",
	subtitle = "Странник без памяти",
	found = "Укрытие Маршалла",
	hint = [=[Поговорите со странником в укрытии, который не помнит, как туда попал.]=],
	allegiance = "Никому, кого он мог бы вспомнить",
	sections = {
		{
			title = "Обзор",
			text = [=[Линкен — {link:gnomes}гном{/link}, который прибыл в {link:un-goro-crater}Кратер Ун'Горо{/link}, не помня, кто он и зачем пришел. Он знает лишь, что его привело сюда нечто важное. В отличие от большинства своих сородичей, он равнодушен к механизмам. {link:j-d-collie}Дж. Д. Колли{/link} подозревает, что в душе он воин.]=],
		},
		{
			title = "Значение",
			text = [=[Его забытое поручение оказывается одним из великих деяний кратера. Он пришел сразиться с {link:blazerunner}Огнебег{/link}ом, окутанным пламенем элементалем Вулкана Огненного Венца, и отнять у него артефакт страшной силы. Когда память возвращается, он не присваивает этот подвиг себе. Он отдает его тому, кто его исцелил.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он пришел в {link:un-goro-crater}Ун'Горо{/link} долгим путем, последним шагом которого была победа над элементалем {link:blazerunner}Огнебег{/link}ом.
• Он искал у жителя Оскверненного леса {link:eridan-bluewind}Эридан{/link}а Синего Ветра тотем, достаточно сильный, чтобы сорвать с этого элементаля его ауру.
• Он намерен унести Золотое Пламя на родину, где этот артефакт больше никогда не послужит злу.]=],
		},
		{
			title = "Неизвестное",
			text = [=[Его родина не названа, и он не сказал, кем был до того, как потерял память.]=],
		},
	},
	chapters = {
		{
			title = "Потерянная сумка",
			hint = "Верните потерянную сумку ее владельцу в укрытии.",
			text = [=[У небольшого пруда лежал разбитый плот — далеко от любой воды, которая могла бы его принести. На дне пруда лежала промокшая сумка: компас, свернутая карта и ключ в виде львиной головы. Линкен посмотрел на них, и что-то в нем шевельнулось. Он вспомнил меч, который должен был закалить, но не вспомнил зачем. Он отослал меч на север, в {link:winterspring}Зимние Ключи{/link}, где живет {link:donova-snowden}Донова Сноуден{/link}.]=],
		},
		{
			title = "Закаленный меч",
			hint = "Проследите, чтобы меч странника был закончен.",
			text = [=[Меч переходил из рук в руки. {link:donova-snowden}Донова{/link} закалила его в своих горячих источниках. Эликсир, который сварил {link:gregan-brewspewer}Греган Пивоплюй{/link} из {link:feralas}Фераласа{/link}, позволил тому, кто нес меч, пройти духом близ {link:gadgetzan}Прибамбасска{/link} и поговорить с призраком по имени {red:gaeriyan}Гаэриан{/red}. Там, под надгробием, меч преобразился во вспышке света. Линкен снова взял его в руки и по-прежнему не мог сказать, для чего он нужен.]=],
		},
		{
			title = "Золотое Пламя",
			hint = "Завершите то, ради чего Линкен пришел в кратер.",
			text = [=[Тотем Аквементаса наконец вернул ему память. Тогда Линкен понял, что пришел сразиться с элементалем {link:blazerunner}Огнебег{/link}ом, который охранял Золотое Пламя. Он понял и то, что сделать это должен уже не он. Когда Огнебег пал и Золотое Пламя принесли страннику, он пообещал унести артефакт домой и беречь его.]=],
		},
	},
	mentions = {
		{ text = "Это тайна для всех" },
		{ text = "Это тайна для всех, потерянная сумка" },
		{ text = "Это тайна для всех, меч" },
		{ text = "Эликсир видения" },
		{ text = "Встреча у могилы" },
		{ text = "Могильное дело" },
		{ text = "Меч Линкена" },
		{ text = "Помощь {link:gnomes}гном{/link}ки" },
		{ text = "Серебряное сердце" },
		{ text = "Аквементас" },
		{ text = "Приключение Линкена" },
		{ text = "Опасно идти одному" },
	},
	bonds = {
		{ id = "j-d-collie", name = "Дж. Д. Колли", note = "запомнила его слова" },
		{ id = "blazerunner", name = "Огнебег", note = "враг, с которым он пришел сразиться" },
		{ id = "donova-snowden", name = "Донова Сноуден", note = "закалила его меч" },
		{ id = "eridan-bluewind", name = "Эридан Синий Ветер", note = "знал, чего он искал" },
	},
})

